import React,{useState}from'react';import{createRoot}from'react-dom/client';
import'../../src/shared/styles/tokens.css';import'../../src/shared/styles/global.css';import'../../src/features/chat/chat.css';import'../../src/features/chat/thread.css';import'../../src/features/chat/messenger.css';import'../../src/features/chat/materials.css';
import Composer from'../../src/features/chat/Composer';import{PhotoGallery}from'../../src/features/chat/messages';import{ChatPresence}from'../../src/features/chat/motion';import{themeStyle}from'../../src/features/chat/ChatAppearance';import{VoiceBubble}from'../../src/features/chat/VoiceBubble';import type{Attachment,Message}from'../../src/features/chat/types';
const images:Attachment[]=[1,2].map(n=>({id:`photo-${n}`,kind:'image',name:`field-${n}.png`,url:`/fixture-photo-${n}.png`,size:100,mimeType:'image/png'}));images.push({id:'video',kind:'video',name:'field.mp4',url:'/fixture-note.mp4',size:1000,mimeType:'video/mp4',duration:2});
const reply:Message={id:'reply',conversationId:'fixture',clientId:'reply',sequence:1,kind:'text',text:'Проверим поле',sender:{id:'peer',name:'Айгерим'},createdAt:new Date().toISOString(),editedAt:null,deletedAt:null,attachments:[],replyTo:null,listing:null,location:null,readByCount:0};
function App(){const[gallery,setGallery]=useState<number|null>(null),[context,setContext]=useState<Message|null>(null),[count,setCount]=useState(0),[failure,setFailure]=useState(true);return <main className="chat-thread" data-chat-theme="nature" style={{...themeStyle({preset:'nature'}),padding:12}}><div style={{flex:1,overflow:'auto'}}><button onClick={()=>setGallery(0)}>Открыть фотографии</button><button onClick={()=>setGallery(2)}>Открыть видео</button><button onClick={()=>setContext(reply)}>Ответить</button><button onClick={()=>setFailure(false)}>Разрешить отправку</button><output data-testid="sent">{count}</output><VoiceBubble file={{id:'voice',url:'/fixture-audio.wav',duration:3,waveform:[.2,.5,.8,.3,.6,.9,.5,.2]}}/></div><Composer conversationId="fixture" userId="fixture-user" disabled={false} reply={context} edit={null} onCancelContext={()=>setContext(null)} onEdit={async()=>{}} onEnqueue={async input=>{if(failure)throw Error('Очередь временно недоступна');setCount(input.files.length);}}/><ChatPresence>{gallery!==null&&<PhotoGallery images={images} initialIndex={gallery} onClose={()=>setGallery(null)}/>}</ChatPresence></main>};createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
